create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique not null,display_name text,role text not null default 'player',created_at timestamptz default now());create table if not exists public.player_progress(id uuid primary key references auth.users(id) on delete cascade,level integer not null default 1,best_score integer not null default 0,health integer not null default 100,skin text not null default 'aurora',last_saved_at timestamptz default now());create table if not exists public.bug_reports(id bigint generated by default as identity primary key,user_id uuid references auth.users(id) on delete set null,title text not null,details text not null,page text,created_at timestamptz default now());alter table public.profiles enable row level security;alter table public.player_progress enable row level security;alter table public.bug_reports enable row level security;create policy "own profile" on public.profiles for select using(auth.uid()=id);create policy "own progress read" on public.player_progress for select using(auth.uid()=id);create policy "own progress write" on public.player_progress for insert with check(auth.uid()=id);create policy "own progress update" on public.player_progress for update using(auth.uid()=id) with check(auth.uid()=id);create policy "signed users report bugs" on public.bug_reports for insert with check(auth.uid()=user_id);create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,display_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1))) on conflict do nothing;insert into public.player_progress(id) values(new.id) on conflict do nothing;return new;end;$$;drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();-- Promote your verified account once: update public.profiles set role='admin' where email='you@example.com';
